import { test } from "node:test";
import assert from "node:assert/strict";
import { pay } from "../src/payments.ts";
import { createStore } from "../src/store.ts";

const request = { key: "demo", customerId: "shopper", amountCents: 1200 };
function controlledGateway() {
  const attempts = [];
  return {
    attempts,
    charge(customerId, amountCents) {
      return new Promise((resolve, reject) => {
        attempts.push({ customerId, amountCents, resolve, reject });
      });
    },
  };
}

// Allow deferred gateway invocation without using timers or releasing charges.
async function flush() { await Promise.resolve(); await Promise.resolve(); }

test("twenty simultaneous retries share one charge and reject simultaneous conflicts", async () => {
  const store = createStore();
  const gateway = controlledGateway();
  const payments = Array.from({ length: 20 }, () => pay(store, gateway, { ...request }));
  const conflicts = Promise.all([
    assert.rejects(pay(store, gateway, { ...request, customerId: "other" }), { message: "KEY_CONFLICT" }),
    assert.rejects(pay(store, gateway, { ...request, amountCents: 1201 }), { message: "KEY_CONFLICT" }),
  ]);
  await flush();
  assert.equal(gateway.attempts.length, 1);
  assert.equal(store.payments.size, 0);
  await conflicts;
  const charge = { id: "ch_1", customerId: request.customerId, amountCents: request.amountCents };
  gateway.attempts[0].resolve(charge);
  const results = await Promise.all(payments);
  for (const result of results) assert.strictEqual(result, charge);
  assert.strictEqual(await pay(store, gateway, request), charge);
  assert.strictEqual(store.payments.get(request.key), charge);
  assert.equal(gateway.attempts.length, 1);
});

test("shared gateway failure reaches every waiter and frees the key for retry", async () => {
  const store = createStore();
  const gateway = controlledGateway();
  const failure = new Error("GATEWAY_UNAVAILABLE");
  const failures = Promise.all(Array.from({ length: 20 }, () =>
    assert.rejects(pay(store, gateway, request), error => error === failure)));
  await flush();
  assert.equal(gateway.attempts.length, 1);
  gateway.attempts[0].reject(failure);
  await failures;
  assert.equal(store.payments.size, 0);
  // A failed reservation must not retain even its previous request details.
  const changed = { ...request, customerId: "other", amountCents: 2 };
  const retries = Array.from({ length: 20 }, () => pay(store, gateway, changed));
  await flush();
  assert.equal(gateway.attempts.length, 2);
  const charge = { id: "ch_retry", customerId: changed.customerId, amountCents: changed.amountCents };
  gateway.attempts[1].resolve(charge);
  for (const result of await Promise.all(retries)) assert.strictEqual(result, charge);
});

test("unrelated keys and separate stores reach the gateway while the first key is pending", async () => {
  const store = createStore();
  const otherStore = createStore();
  const gateway = controlledGateway();
  const first = pay(store, gateway, request);
  const second = pay(store, gateway, { ...request, key: "other" });
  const third = pay(otherStore, gateway, request);
  await flush();
  assert.equal(gateway.attempts.length, 3);
  const charges = gateway.attempts.map((attempt, i) => ({ id: `ch_${i}`, customerId: attempt.customerId, amountCents: attempt.amountCents }));
  gateway.attempts[1].resolve(charges[1]);
  gateway.attempts[2].resolve(charges[2]);
  assert.strictEqual(await second, charges[1]);
  assert.strictEqual(await third, charges[2]);
  assert.equal(store.payments.has(request.key), false);
  gateway.attempts[0].resolve(charges[0]);
  assert.strictEqual(await first, charges[0]);
});

test("synchronous gateway throws also clear in-flight reservations", async () => {
  const store = createStore();
  const failure = new Error("sync failure");
  let attempts = 0;
  const charge = { id: "ch_retry", customerId: request.customerId, amountCents: request.amountCents };
  const gateway = { charge() { if (++attempts === 1) throw failure; return charge; } };
  await assert.rejects(pay(store, gateway, request), error => error === failure);
  assert.equal(store.payments.size, 0);
  assert.strictEqual(await pay(store, gateway, request), charge);
  assert.equal(attempts, 2);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { createStore } from "../src/store.ts";
import { Gateway } from "../src/gateway.ts";
import { pay } from "../src/payments.ts";

const request = Object.freeze({ key: "demo", customerId: "shopper", amountCents: 1200 });

test("sequential retries return the original successful charge object", async () => {
  const store = createStore();
  const gateway = new Gateway();
  const original = await pay(store, gateway, request);
  for (let i = 0; i < 3; i++) {
    assert.strictEqual(await pay(store, gateway, { ...request }), original);
  }
  assert.strictEqual(store.payments.get(request.key), original);
  assert.equal(gateway.calls.length, 1);
});

test("conflicting customer or amount rejects without charging or replacing the original", async () => {
  const store = createStore();
  const gateway = new Gateway();
  const original = await pay(store, gateway, request);
  for (const change of [{ customerId: "other" }, { amountCents: 1201 }]) {
    await assert.rejects(pay(store, gateway, { ...request, ...change }), { message: "KEY_CONFLICT" });
  }
  assert.equal(gateway.calls.length, 1);
  assert.strictEqual(await pay(store, gateway, request), original);
});

test("stores and distinct keys are independent", async () => {
  const gateway = new Gateway();
  const firstStore = createStore();
  const secondStore = createStore();
  const first = await pay(firstStore, gateway, request);
  const second = await pay(secondStore, gateway, request);
  const third = await pay(firstStore, gateway, { ...request, key: "other" });
  assert.notStrictEqual(first, second);
  assert.notStrictEqual(first, third);
  assert.equal(gateway.calls.length, 3);
});

test("invalid requests reject before any gateway access or store mutation", async () => {
  const invalid = [undefined, null, {}, ...["key", "customerId"].flatMap(field =>
    [undefined, null, "", " \t\n", 123, {}, []].map(value => ({ ...request, [field]: value }))
  ), ...[undefined, null, 0, -1, 1.5, NaN, Infinity, -Infinity, Number.MAX_SAFE_INTEGER + 1, "1200", true, 1n]
    .map(amountCents => ({ ...request, amountCents }))];
  const gateway = { get charge() { assert.fail("gateway accessed for invalid request"); } };
  for (const input of invalid) {
    const store = createStore();
    await assert.rejects(pay(store, gateway, input), { message: "INVALID_REQUEST" });
    assert.equal(store.payments.size, 0);
  }
  const store = createStore();
  const original = await pay(store, new Gateway(), request);
  await assert.rejects(pay(store, gateway, { ...request, amountCents: 0 }), { message: "INVALID_REQUEST" });
  assert.strictEqual(store.payments.get(request.key), original);
});

test("validation preserves identifiers and accepts positive safe integer boundaries", async () => {
  const store = createStore();
  const gateway = new Gateway();
  const padded = Object.freeze({ key: " demo ", customerId: " shopper ", amountCents: 1 });
  const charge = await pay(store, gateway, padded);
  assert.equal(charge.customerId, " shopper ");
  assert.strictEqual(store.payments.get(" demo "), charge);
  assert.equal(store.payments.has("demo"), false);
  assert.strictEqual(await pay(store, gateway, padded), charge);
  await assert.rejects(pay(store, gateway, { ...padded, customerId: "shopper" }), { message: "KEY_CONFLICT" });
  const max = await pay(store, gateway, { ...request, amountCents: Number.MAX_SAFE_INTEGER });
  assert.equal(max.amountCents, Number.MAX_SAFE_INTEGER);
  assert.equal(gateway.calls.length, 2);
});

test("gateway failure leaves no payment and permits a successful retry", async () => {
  const store = createStore();
  const gateway = new Gateway();
  gateway.failNext = true;
  await assert.rejects(pay(store, gateway, request), { message: "GATEWAY_UNAVAILABLE" });
  assert.equal(store.payments.size, 0);
  assert.equal(gateway.calls.length, 0);
  const original = await pay(store, gateway, request);
  assert.strictEqual(await pay(store, gateway, request), original);
  assert.equal(gateway.calls.length, 1);
});

test("gateway errors propagate unchanged and failed keys do not bind request details", async () => {
  const store = createStore();
  const failure = new Error("gateway failure");
  const gateway = { charge: async () => { throw failure; } };
  await assert.rejects(pay(store, gateway, request), error => error === failure);
  assert.equal(store.payments.size, 0);
  const healthyGateway = new Gateway();
  const changed = { ...request, customerId: "other", amountCents: 2 };
  const charge = await pay(store, healthyGateway, changed);
  assert.strictEqual(await pay(store, healthyGateway, changed), charge);
  assert.equal(healthyGateway.calls.length, 1);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { createStore } from "../src/store.ts";
import { Gateway } from "../src/gateway.ts";
import { pay } from "../src/payments.ts";
test("one payment returns a charge", async () => {
  const result = await pay(createStore(), new Gateway(), { key: "demo", customerId: "shopper", amountCents: 1200 });
