import { test } from "node:test";
import assert from "node:assert/strict";
import * as payments from "../src/payments.ts";
import * as stores from "../src/store.ts";
import * as gateways from "../src/gateway.ts";

const request = { key: "first", customerId: "shopper", amountCents: 1200 };
const flush = async () => { await Promise.resolve(); await Promise.resolve(); };

function controlledGateway() {
  const attempts = [];
  return {
    attempts,
    charge(customerId, amountCents) {
      return new Promise((resolve, reject) => attempts.push({ customerId, amountCents, resolve, reject }));
    },
  };
}

test("public exports and store shape remain compatible", () => {
  assert.deepEqual(Object.keys(payments).sort(), ["handleWebhook", "pay"]);
  assert.deepEqual(Object.keys(stores), ["createStore"]);
  assert.deepEqual(Object.keys(gateways), ["Gateway"]);
  const store = stores.createStore();
  assert.deepEqual(Object.keys(store).sort(), ["events", "payments", "receipts"]);
  assert.ok(store.payments instanceof Map);
  assert.ok(store.events instanceof Set);
  assert.ok(Array.isArray(store.receipts));
});

test("failed-key cleanup preserves other reservations through retry and completion", async () => {
  const store = stores.createStore();
  const gateway = controlledGateway();
  const failure = new Error("timeout");
  const failed = assert.rejects(payments.pay(store, gateway, request), error => error === failure);
  const otherRequest = { ...request, key: "second" };
  const other = payments.pay(store, gateway, otherRequest);
  await flush();
  assert.equal(gateway.attempts.length, 2);
  gateway.attempts[0].reject(failure);
  await failed;
  const otherRetry = payments.pay(store, gateway, otherRequest);
  const retry = payments.pay(store, gateway, request);
  await flush();
  assert.equal(gateway.attempts.length, 3);
  const retriedCharge = { id: "ch_retry", customerId: request.customerId, amountCents: request.amountCents };
  gateway.attempts[2].resolve(retriedCharge);
  assert.strictEqual(await retry, retriedCharge);
  const lastOtherRetry = payments.pay(store, gateway, otherRequest);
  await flush();
  assert.equal(gateway.attempts.length, 3);
  const otherCharge = { ...retriedCharge, id: "ch_other" };
  gateway.attempts[1].resolve(otherCharge);
  for (const result of await Promise.all([other, otherRetry, lastOtherRetry])) {
    assert.strictEqual(result, otherCharge);
  }
  assert.equal(store.payments.size, 2);
});

test("invalid in-flight retry cannot touch gateway or disturb the valid reservation", async () => {
  const store = stores.createStore();
  const gateway = controlledGateway();
  const original = payments.pay(store, gateway, request);
  const inaccessibleGateway = { get charge() { assert.fail("invalid retry accessed gateway"); } };
  await assert.rejects(payments.pay(store, inaccessibleGateway, { ...request, amountCents: NaN }), { message: "INVALID_REQUEST" });
  const retry = payments.pay(store, gateway, request);
  await flush();
  assert.equal(gateway.attempts.length, 1);
  assert.equal(store.payments.size, 0);
  const charge = { id: "ch_1", customerId: request.customerId, amountCents: request.amountCents };
  gateway.attempts[0].resolve(charge);
  for (const result of await Promise.all([original, retry])) assert.strictEqual(result, charge);
});

test("callbacks reconcile preexisting receipts and an invalid ID remains usable", async () => {
  const store = stores.createStore();
  const original = Object.freeze({ id: "old", chargeId: "ch_1", type: "payment.succeeded" });
  store.receipts.push(original);
  store.events.add(original.id);
  const incoming = Object.freeze({ ...original, id: "new" });
  await assert.rejects(payments.handleWebhook(store, { ...incoming, type: "payment.failed" }), { message: "INVALID_EVENT" });
  assert.equal(store.events.has("new"), false);
  assert.deepEqual(await payments.handleWebhook(store, incoming), { accepted: true });
  assert.deepEqual(await payments.handleWebhook(store, incoming), { accepted: false });
  assert.deepEqual([...store.events], ["old", "new"]);
  assert.equal(store.receipts.length, 1);
  assert.strictEqual(store.receipts[0], original);
});

test("twenty real-gateway retries and repeated callbacks yield one charge and receipt", async () => {
  const store = stores.createStore();
  const gateway = new gateways.Gateway();
  const charges = await Promise.all(Array.from({ length: 20 }, () => payments.pay(store, gateway, request)));
  for (const charge of charges) assert.strictEqual(charge, charges[0]);
  const event = { id: "evt_1", chargeId: charges[0].id, type: "payment.succeeded" };
  const results = await Promise.all([
    payments.handleWebhook(store, event),
    payments.handleWebhook(store, { ...event }),
    payments.handleWebhook(store, { ...event, id: "evt_2" }),
  ]);
  assert.deepEqual(results, [{ accepted: true }, { accepted: false }, { accepted: true }]);
  assert.strictEqual(await payments.pay(store, gateway, request), charges[0]);
  assert.equal(gateway.calls.length, 1);
  assert.equal(store.events.size, 2);
  assert.equal(store.receipts.length, 1);
  assert.strictEqual(store.receipts[0], event);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { handleWebhook, pay } from "../src/payments.ts";
import { createStore } from "../src/store.ts";
import { Gateway } from "../src/gateway.ts";

const event = Object.freeze({ id: "evt_1", chargeId: "ch_1", type: "payment.succeeded" });

test("first delivery retains the original event; repeated event IDs are not accepted", async () => {
  const store = createStore();
  assert.deepEqual(await handleWebhook(store, event), { accepted: true });
  assert.strictEqual(store.receipts[0], event);
  assert.deepEqual(await handleWebhook(store, { ...event }), { accepted: false });
  assert.deepEqual(await handleWebhook(store, { ...event, chargeId: "ch_other" }), { accepted: false });
  assert.deepEqual([...store.events], [event.id]);
  assert.equal(store.receipts.length, 1);
  assert.strictEqual(store.receipts[0], event);
});

test("distinct event IDs for one charge are accepted and recorded with only the original receipt", async () => {
  const store = createStore();
  const second = { ...event, id: "evt_2" };
  const third = { ...event, id: "evt_3", chargeId: "ch_2" };
  for (const input of [event, second, third]) {
    assert.deepEqual(await handleWebhook(store, input), { accepted: true });
  }
  assert.deepEqual([...store.events], ["evt_1", "evt_2", "evt_3"]);
  assert.equal(store.receipts.length, 2);
  assert.strictEqual(store.receipts[0], event);
  assert.strictEqual(store.receipts[1], third);
  assert.deepEqual(await handleWebhook(store, second), { accepted: false });
});

test("invalid callbacks reject without mutation, even for previously seen IDs", async () => {
  const invalid = [undefined, null, {}, ...["id", "chargeId"].flatMap(field =>
    [undefined, null, "", " \t\n", 1, {}, []].map(value => ({ ...event, [field]: value }))
  ), ...[undefined, null, "", "payment.failed", " payment.succeeded", 1]
    .map(type => ({ ...event, type }))];
  for (const populated of [false, true]) {
    const store = createStore();
    if (populated) await handleWebhook(store, event);
    const eventsBefore = [...store.events];
    const receiptsBefore = [...store.receipts];
    for (const input of invalid) {
      await assert.rejects(handleWebhook(store, input), { message: "INVALID_EVENT" });
      assert.deepEqual([...store.events], eventsBefore);
      assert.deepEqual(store.receipts, receiptsBefore);
    }
  }
});

test("overlapping deliveries deduplicate event IDs and charge receipts", async () => {
  const store = createStore();
  const deliveries = [event, ...Array.from({ length: 20 }, () => ({ ...event })),
    ...Array.from({ length: 20 }, (_, i) => ({ ...event, id: `other_${i}` }))];
  const results = await Promise.all(deliveries.map(input => handleWebhook(store, input)));
  assert.equal(results.filter(result => result.accepted).length, 21);
  assert.equal(store.events.size, 21);
  assert.equal(store.receipts.length, 1);
  assert.strictEqual(store.receipts[0], event);
});

test("callback state is store-local and does not alter payment retry behavior", async () => {
  const store = createStore();
  const otherStore = createStore();
  const gateway = new Gateway();
  const request = { key: "demo", customerId: "shopper", amountCents: 1200 };
  const payment = await pay(store, gateway, request);
  assert.deepEqual(await handleWebhook(store, event), { accepted: true });
  assert.deepEqual(await handleWebhook(otherStore, event), { accepted: true });
  assert.strictEqual(await pay(store, gateway, request), payment);
  assert.equal(gateway.calls.length, 1);
  assert.equal(store.payments.size, 1);
  assert.equal(otherStore.payments.size, 0);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { pay } from "../src/payments.ts";
import { createStore } from "../src/store.ts";

const request = { key: "demo", customerId: "shopper", amountCents: 1200 };
function deferred() {
  let resolve, reject;
  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
  return { promise, resolve, reject };
}
function controlledGateway() {
  const attempts = [];
  return {
    attempts,
    charge(customerId, amountCents) {
      const gate = deferred();
      const charge = { id: `ch_${attempts.length + 1}`, customerId, amountCents };
      attempts.push({ ...gate, charge });
      return gate.promise;
    },
  };
}

test("twenty simultaneous retries share a charge and reject in-flight conflicts", async () => {
  const store = createStore();
  const gateway = controlledGateway();
  const first = pay(store, gateway, request);
  const retries = Array.from({ length: 20 }, () => pay(store, gateway, { ...request }));
  const conflicts = [
    pay(store, gateway, { ...request, customerId: "other" }),
    pay(store, gateway, { ...request, amountCents: 1201 }),
  ];
  const conflictChecks = conflicts.map(promise => assert.rejects(promise, { message: "KEY_CONFLICT" }));
  await Promise.resolve();
  assert.equal(gateway.attempts.length, 1);
  assert.equal(store.payments.size, 0);
  await Promise.all(conflictChecks);
  const { charge, resolve } = gateway.attempts[0];
  resolve(charge);
  const results = await Promise.all([first, ...retries]);
  for (const result of results) assert.strictEqual(result, charge);
  assert.strictEqual(await pay(store, gateway, request), charge);
  assert.strictEqual(store.payments.get(request.key), charge);
  assert.equal(gateway.attempts.length, 1);
});

test("shared failure rejects every waiter and releases the key for retry", async () => {
  const store = createStore();
  const gateway = controlledGateway();
  const error = new Error("GATEWAY_UNAVAILABLE");
  const requests = Array.from({ length: 20 }, () => pay(store, gateway, request));
  const outcomes = Promise.allSettled(requests);
  await Promise.resolve();
  assert.equal(gateway.attempts.length, 1);
  gateway.attempts[0].reject(error);
  for (const outcome of await outcomes) {
    assert.equal(outcome.status, "rejected");
    assert.strictEqual(outcome.reason, error);
  }
  assert.equal(store.payments.size, 0);
  const changed = { ...request, amountCents: 2400 };
  const retries = Array.from({ length: 20 }, () => pay(store, gateway, changed));
  await Promise.resolve();
  assert.equal(gateway.attempts.length, 2);
  const attempt = gateway.attempts[1];
  attempt.resolve(attempt.charge);
  for (const result of await Promise.all(retries)) assert.strictEqual(result, attempt.charge);
  assert.strictEqual(store.payments.get(request.key), attempt.charge);
});

test("unrelated keys and separate stores reach the gateway without waiting", async () => {
  const store = createStore();
  const otherStore = createStore();
  const gateway = controlledGateway();
  const first = pay(store, gateway, request);
  const second = pay(store, gateway, { ...request, key: "other" });
  const third = pay(otherStore, gateway, request);
  await Promise.resolve();
  assert.equal(gateway.attempts.length, 3);
  gateway.attempts[1].resolve(gateway.attempts[1].charge);
  gateway.attempts[2].resolve(gateway.attempts[2].charge);
  await Promise.all([second, third]);
  assert.equal(store.payments.has(request.key), false);
  gateway.attempts[0].resolve(gateway.attempts[0].charge);
  await first;
  assert.equal(store.payments.size, 2);
  assert.equal(otherStore.payments.size, 1);
});

test("synchronous gateway throws are shared and do not poison the reservation", async () => {
  const store = createStore();
  const error = new Error("synchronous failure");
  let calls = 0;
  const charge = { id: "ch_1", customerId: request.customerId, amountCents: request.amountCents };
  const gateway = { charge() { calls++; if (calls === 1) throw error; return charge; } };
  const outcomes = await Promise.allSettled(Array.from({ length: 20 }, () => pay(store, gateway, request)));
  assert.equal(calls, 1);
  for (const outcome of outcomes) {
    assert.equal(outcome.status, "rejected");
    assert.strictEqual(outcome.reason, error);
  }
  assert.equal(store.payments.size, 0);
  assert.strictEqual(await pay(store, gateway, request), charge);
  assert.equal(calls, 2);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { pay } from "../src/payments.ts";
import { Gateway } from "../src/gateway.ts";
import { createStore } from "../src/store.ts";

const request = Object.freeze({ key: "demo", customerId: "shopper", amountCents: 1200 });

test("sequential retries return the original successful charge object", async () => {
  const store = createStore();
  const gateway = new Gateway();
  const original = await pay(store, gateway, request);
  for (let i = 0; i < 3; i++) {
    assert.strictEqual(await pay(store, gateway, { ...request }), original);
  }
  assert.strictEqual(original, gateway.calls[0]);
  assert.strictEqual(store.payments.get(request.key), original);
  assert.equal(gateway.calls.length, 1);
});

test("customer and amount conflicts reject before gateway access", async () => {
  const store = createStore();
  const gateway = new Gateway();
  const original = await pay(store, gateway, request);
  const forbiddenGateway = { charge() { assert.fail("must not charge"); } };
  for (const changes of [{ customerId: "other" }, { amountCents: 1201 }]) {
    await assert.rejects(pay(store, forbiddenGateway, { ...request, ...changes }), { message: "KEY_CONFLICT" });
  }
  assert.strictEqual(await pay(store, forbiddenGateway, request), original);
  assert.equal(store.payments.size, 1);
  assert.equal(gateway.calls.length, 1);
});

test("keys and stores are independent", async () => {
  const store = createStore();
  const otherStore = createStore();
  const gateway = new Gateway();
  const first = await pay(store, gateway, request);
  const second = await pay(store, gateway, { ...request, key: "other" });
  const third = await pay(otherStore, gateway, request);
  assert.notStrictEqual(first, second);
  assert.notStrictEqual(first, third);
  assert.equal(gateway.calls.length, 3);
  assert.equal(store.payments.size, 2);
  assert.equal(otherStore.payments.size, 1);
});

test("invalid requests reject before gateway access or state changes", async () => {
  const store = createStore();
  const original = await pay(store, new Gateway(), request);
  const gateway = { charge() { assert.fail("invalid request reached gateway"); } };
  const invalid = [undefined, null, {}, 42, "request"];
  for (const field of ["key", "customerId"]) {
    for (const value of [undefined, null, "", " \t\n", 1, {}, []]) {
      invalid.push({ ...request, [field]: value });
    }
  }
  for (const amountCents of [undefined, null, 0, -1, 1.5, NaN, Infinity, -Infinity, Number.MAX_SAFE_INTEGER + 1, "1200", true, 1n]) {
    invalid.push({ ...request, amountCents });
