  const invalid = [undefined, null, {}, ...["id", "chargeId"].flatMap(field =>
    [undefined, null, "", " \t\n", 0, true, [], {}].map(value => ({ ...event, [field]: value }))
  ), ...[undefined, null, "", "payment.failed", " payment.succeeded ", 1].map(type => ({ ...event, type }))];
  for (const input of invalid) {
