import { test } from "node:test";
import assert from "node:assert/strict";
import { createStore } from "../src/store.ts";
import { Gateway } from "../src/gateway.ts";
import { handleWebhook, pay } from "../src/payments.ts";
test("one payment returns a charge", async () => {
  const result = await pay(createStore(), new Gateway(), { key: "demo", customerId: "shopper", amountCents: 1200 });
  assert.equal(result.amountCents, 1200);
});

test("repeating a key returns the original charge without charging again", async () => {
  const store = createStore();
  const gateway = new Gateway();
  const request = { key: "demo", customerId: "shopper", amountCents: 1200 };

  const first = await pay(store, gateway, request);
  const second = await pay(store, gateway, request);

  assert.strictEqual(second, first);
  assert.equal(gateway.calls.length, 1);
});

test("a key conflict is rejected before the gateway is called", async () => {
  const store = createStore();
  const gateway = new Gateway();
  await pay(store, gateway, { key: "demo", customerId: "shopper", amountCents: 1200 });

  await assert.rejects(
    pay(store, gateway, { key: "demo", customerId: "other-shopper", amountCents: 1200 }),
    { message: "KEY_CONFLICT" }
  );
  assert.equal(gateway.calls.length, 1);
});

test("invalid requests are rejected before gateway access", async () => {
  const gateway = new Gateway();
  for (const request of [
    { key: " ", customerId: "shopper", amountCents: 1200 },
    { key: "demo", customerId: " ", amountCents: 1200 },
    { key: "demo", customerId: "shopper", amountCents: 0 },
    { key: "demo", customerId: "shopper", amountCents: 1.5 },
    { key: "demo", customerId: "shopper", amountCents: Number.MAX_SAFE_INTEGER + 1 }
  ]) {
    await assert.rejects(pay(createStore(), gateway, request), { message: "INVALID_REQUEST" });
  }
  assert.equal(gateway.calls.length, 0);
});

test("a failed charge does not poison the key and can be retried", async () => {
  const store = createStore();
  const gateway = new Gateway();
  const request = { key: "demo", customerId: "shopper", amountCents: 1200 };
  gateway.failNext = true;

  await assert.rejects(pay(store, gateway, request), { message: "GATEWAY_UNAVAILABLE" });
  const charge = await pay(store, gateway, request);

  assert.equal(charge.amountCents, 1200);
  assert.equal(gateway.calls.length, 1);
});

test("twenty identical in-flight retries share one charge and conflicts reject", async () => {
  const store = createStore();
  const calls = [];
  const gateway = {
    charge(customerId, amountCents) {
      calls.push({ customerId, amountCents });
      return new Promise((resolve) => {
        this.resolve = resolve;
      });
    },
    resolve: undefined
  };
  const request = { key: "demo", customerId: "shopper", amountCents: 1200 };
  const attempts = Array.from({ length: 20 }, () => pay(store, gateway, request));
  const conflict = pay(store, gateway, { ...request, amountCents: 1300 });

  await assert.rejects(conflict, { message: "KEY_CONFLICT" });
  assert.equal(calls.length, 1);
  const charge = { id: "ch_shared", ...request };
  gateway.resolve(charge);
  const results = await Promise.all(attempts);

  assert.equal(new Set(results).size, 1);
  assert.strictEqual(results[0], charge);
  assert.equal(calls.length, 1);
});

test("different keys reach the gateway concurrently", async () => {
  const store = createStore();
  const calls = [];
  const resolvers = [];
  const gateway = {
    charge(customerId, amountCents) {
      calls.push({ customerId, amountCents });
      return new Promise((resolve) => resolvers.push(resolve));
    }
  };

  const first = pay(store, gateway, { key: "first", customerId: "one", amountCents: 100 });
  const second = pay(store, gateway, { key: "second", customerId: "two", amountCents: 200 });
  assert.equal(calls.length, 2);
  assert.equal(resolvers.length, 2);

  resolvers[1]({ id: "ch_second", customerId: "two", amountCents: 200 });
  resolvers[0]({ id: "ch_first", customerId: "one", amountCents: 100 });
  await Promise.all([first, second]);
});

test("a failed shared attempt clears the reservation for a retry", async () => {
  const store = createStore();
  let rejectFirst;
  let calls = 0;
  const gateway = {
    charge() {
      calls += 1;
      if (calls === 1) {
        return new Promise((_, reject) => { rejectFirst = reject; });
      }
      return Promise.resolve({ id: "ch_retry", customerId: "shopper", amountCents: 1200 });
    }
  };
  const request = { key: "demo", customerId: "shopper", amountCents: 1200 };
  const attempts = Array.from({ length: 20 }, () => pay(store, gateway, request));
  rejectFirst(new Error("GATEWAY_UNAVAILABLE"));

  await assert.rejects(Promise.all(attempts), { message: "GATEWAY_UNAVAILABLE" });
  const retry = await pay(store, gateway, request);

  assert.equal(retry.id, "ch_retry");
  assert.equal(calls, 2);
});

